-- New isolated alpha_role_probe database only. No runtime superuser or credential.
CREATE ROLE alpha_entity LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS CONNECTION LIMIT 2;
ALTER ROLE alpha_entity SET search_path=pg_catalog;
ALTER ROLE alpha_entity SET statement_timeout='15s';
ALTER ROLE alpha_entity SET lock_timeout='1s';
CREATE ROLE alpha_typed LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS CONNECTION LIMIT 2;
ALTER ROLE alpha_typed SET search_path=pg_catalog;
ALTER ROLE alpha_typed SET statement_timeout='15s';
ALTER ROLE alpha_typed SET lock_timeout='1s';
CREATE ROLE alpha_config LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS CONNECTION LIMIT 2;
ALTER ROLE alpha_config SET search_path=pg_catalog;
ALTER ROLE alpha_config SET statement_timeout='15s';
ALTER ROLE alpha_config SET lock_timeout='1s';
CREATE ROLE alpha_account LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS CONNECTION LIMIT 2;
ALTER ROLE alpha_account SET search_path=pg_catalog;
ALTER ROLE alpha_account SET statement_timeout='15s';
ALTER ROLE alpha_account SET lock_timeout='1s';
REVOKE ALL ON DATABASE alpha_role_probe, postgres, template1 FROM PUBLIC;
REVOKE ALL ON SCHEMA public,config,data,friend,guild,admin FROM PUBLIC;
